inline act_t clamp_fixed(act_t x, act_t xmin, act_t xmax) {
#pragma HLS INLINE
 return (x < xmin) ? xmin : (x > xmax) ? xmax : x;
}

inline void sigmoid(act_t* res, act_t* x, int size) {
#pragma HLS INLINE off
 for (int i = 0; i < size; ++i) {
#pragma HLS UNROLL factor=5
 if (x[i] > act_t(8)) res[i] = act_t(1);
        else if (x[i] < act_t(-8)) res[i] = act_t(0);
        else {
            const ap_uint<8> idx = (ap_uint<8>)((temp_t(x[i]) + temp_t(8)) * temp_t(15.9375));
            res[i] = sigmoid_lut[idx];
        }
    }
}

inline void tanh(act_t* res, act_t* x, int size) {
#pragma HLS INLINE off
 for (int i = 0; i < size; ++i) {
#pragma HLS UNROLL factor=5
 if (x[i] > act_t(4)) res[i] = act_t(1);
        else if (x[i] < act_t(-4)) res[i] = act_t(-1);
        else {
            const ap_uint<8> idx = (ap_uint<8>)((temp_t(x[i]) + temp_t(4)) * temp_t(31.875));
            res[i] = tanh_lut[idx];
        }
    }
}

inline ap_uint<4> compute_gate_mask(const act_t x_t[39], const act_t x_prev[39]) {_ssdm_SpecArrayDimSize(x_t, 39);_ssdm_SpecArrayDimSize(x_prev, 39);
#pragma HLS INLINE
 temp_t diff_sum = 0;
    temp_t energy = 0;

    for (int i = 0; i < 39; ++i) {
#pragma HLS PIPELINE II=1
 temp_t delta = x_t[i] - x_prev[i];
        diff_sum += (delta >= temp_t(0)) ? temp_t(delta): temp_t(-delta);
        energy += (temp_t(x_t[i]) >= temp_t(0)) ? temp_t(x_t[i]) : temp_t(-x_t[i]);
    }

    bool skip_by_delta = (diff_sum < 1.5);
    bool skip_by_energy = (energy < 0.01);

    return (skip_by_delta || skip_by_energy) ? ap_uint<4>(0b0000) : ap_uint<4>(0b1111);
}

inline void step_lstm_optimized(
    const act_t x_t[39],
    act_t h_t[50],
    act_t c_t[50],
    const weight_t Wi[50][39 + 50],
    const weight_t Wf[50][39 + 50],
    const weight_t Wg[50][39 + 50],
    const weight_t Wo[50][39 + 50],
    const weight_t Bi[50],
    const weight_t Bf[50],
    const weight_t Bg[50],
    const weight_t Bo[50],
    const ap_uint<4> gate_mask,
    const bool use_prev_output,
    act_t prev_h[50],
    act_t prev_c[50]
) {_ssdm_SpecArrayDimSize(x_t, 39);_ssdm_SpecArrayDimSize(h_t, 50);_ssdm_SpecArrayDimSize(c_t, 50);_ssdm_SpecArrayDimSize(Wi, 50);_ssdm_SpecArrayDimSize(Wf, 50);_ssdm_SpecArrayDimSize(Wg, 50);_ssdm_SpecArrayDimSize(Wo, 50);_ssdm_SpecArrayDimSize(Bi, 50);_ssdm_SpecArrayDimSize(Bf, 50);_ssdm_SpecArrayDimSize(Bg, 50);_ssdm_SpecArrayDimSize(Bo, 50);_ssdm_SpecArrayDimSize(prev_h, 50);_ssdm_SpecArrayDimSize(prev_c, 50);
#pragma HLS INLINE off
 act_t x_h[39 + 50];
#pragma HLS ARRAY_PARTITION variable=&x_h complete

 act_t i_[50], f[50], g[50], o[50];
#pragma HLS ARRAY_PARTITION variable=&i_ cyclic factor=5
#pragma HLS ARRAY_PARTITION variable=&f cyclic factor=5
#pragma HLS ARRAY_PARTITION variable=&g cyclic factor=5
#pragma HLS ARRAY_PARTITION variable=&o cyclic factor=5

 for (int i = 0; i < 39; ++i) x_h[i] = x_t[i];
    for (int i = 0; i < 50; ++i) x_h[39 + i] = use_prev_output ? prev_h[i] : h_t[i];

    for (int i = 0; i < 50; ++i) {
#pragma HLS UNROLL factor=5
 i_[i] = Bi[i]; f[i] = Bf[i]; g[i] = Bg[i]; o[i] = Bo[i];
    }

    for (int j = 0; j < 39 + 50; ++j) {
#pragma HLS PIPELINE II=1
 act_t xj = x_h[j];
        for (int i = 0; i < 50; ++i) {
#pragma HLS UNROLL factor=5
 if (gate_mask[0]) i_[i] += Wi[i][j] * xj;
            if (gate_mask[1]) f[i] += Wf[i][j] * xj;
            if (gate_mask[2]) g[i] += Wg[i][j] * xj;
            if (gate_mask[3]) o[i] += Wo[i][j] * xj;
        }
    }

    if (gate_mask[0]) sigmoid(i_, i_, 50);
    if (gate_mask[1]) sigmoid(f, f, 50);
    if (gate_mask[2]) tanh(g, g, 50);
    if (gate_mask[3]) sigmoid(o, o, 50);

    for (int j = 0; j < 50; ++j) {
#pragma HLS UNROLL factor=5
 act_t prev_cj = use_prev_output ? prev_c[j] : c_t[j];
        c_t[j] = f[j] * prev_cj + i_[j] * g[j];
        temp_t temp_x = clamp_fixed(c_t[j], -4, 4);
        const ap_uint<8> idx = ap_uint<8>((temp_x + temp_t(4)) * temp_t(31.875));
        h_t[j] = o[j] * tanh_lut[idx];
        if (use_prev_output) { prev_h[j] = h_t[j]; prev_c[j] = c_t[j]; }
    }
}



void lstm_infer(float input[100 * 39], int valid_len, float ress[10]) {_ssdm_SpecArrayDimSize(input, 3900);_ssdm_SpecArrayDimSize(ress, 10);
#pragma HLS DATAFLOW


 act_t h_f[50] = {0}, c_f[50] = {0};
    act_t h_b[50] = {0}, c_b[50] = {0};
    act_t prev_h_f[50] = {0}, prev_c_f[50] = {0};
    act_t prev_h_b[50] = {0}, prev_c_b[50] = {0};
    act_t x_prev_f[39] = {0}, x_prev_b[39] = {0};

#pragma HLS ARRAY_PARTITION variable=&h_f cyclic factor=5
#pragma HLS ARRAY_PARTITION variable=&h_b cyclic factor=5
#pragma HLS ARRAY_PARTITION variable=&prev_h_f cyclic factor=5
#pragma HLS ARRAY_PARTITION variable=&prev_h_b cyclic factor=5

 act_t x_f[39], x_b[39];
    act_t h_cat[2 * 50];
    act_t fc1[50], fc2[10];
#pragma HLS ARRAY_PARTITION variable=&h_cat complete
#pragma HLS ARRAY_PARTITION variable=&fc1 cyclic factor=5
#pragma HLS ARRAY_PARTITION variable=&fc2 complete

 float out[10];
    int stable_count = 0, last_pred = -1;

    for (int t = 0; t < valid_len; ++t) {

        for (int i = 0; i < 39; ++i) {
#pragma HLS UNROLL factor=3
 x_f[i] = input[t * 39 + i];
            x_b[i] = input[(valid_len - 1 - t) * 39 + i];
        }


        ap_uint<4> mask_f = compute_gate_mask(x_f, x_prev_f);
        ap_uint<4> mask_b = compute_gate_mask(x_b, x_prev_b);


        for (int i = 0; i < 39; ++i) {
#pragma HLS UNROLL factor=3
 x_prev_f[i] = x_f[i];
            x_prev_b[i] = x_b[i];
        }


        step_lstm_optimized(
            x_f, h_f, c_f,
            Weight_i_f, Weight_f_f, Weight_g_f, Weight_o_f,
            Bias_i_f, Bias_f_f, Bias_g_f, Bias_o_f,
            mask_f, (mask_f != 0b1111), prev_h_f, prev_c_f
        );

        step_lstm_optimized(
            x_b, h_b, c_b,
            Weight_i_b, Weight_f_b, Weight_g_b, Weight_o_b,
            Bias_i_b, Bias_f_b, Bias_g_b, Bias_o_b,
            mask_b, (mask_b != 0b1111), prev_h_b, prev_c_b
        );


        for (int i = 0; i < 50; ++i) {
#pragma HLS UNROLL factor=5
 h_cat[i] = h_f[i];
            h_cat[50 + i] = h_b[i];
        }


        for (int i = 0; i < 50; ++i) {
#pragma HLS UNROLL factor=5
 fc1[i] = Bias_fc1[i];
        }
        for (int j = 0; j < 2 * 50; ++j) {
#pragma HLS PIPELINE
 act_t xj = h_cat[j];
            for (int i = 0; i < 50; ++i) {
#pragma HLS UNROLL factor=5
 fc1[i] += Weight_fc1[i][j] * xj;
            }
        }


        for (int i = 0; i < 10; ++i) {
#pragma HLS UNROLL
 fc2[i] = Bias_fc2[i];
        }
        for (int j = 0; j < 50; ++j) {
#pragma HLS PIPELINE
 act_t relu = fc1[j] > 0 ? fc1[j] : act_t(0);
            for (int i = 0; i < 10; ++i) {
#pragma HLS UNROLL factor=2
 fc2[i] += Weight_fc2[i][j] * relu;
            }
        }


        float max_val = -__builtin_inf(), second_max = -__builtin_inf();
        int argmax = -1;
        for (int i = 0; i < 10; ++i) {
            out[i] = float(fc2[i]);
            if (out[i] > max_val) {
                second_max = max_val;
                max_val = out[i];
                argmax = i;
            } else if (out[i] > second_max) {
                second_max = out[i];
            }
        }

        if (argmax == last_pred && (max_val - second_max) > 6.8) {
            if (++stable_count >= 3) {
                for (int i = 0; i < 10; ++i) {
#pragma HLS UNROLL
 ress[i] = out[i];
                }
                return;
            }
        } else {
            stable_count = 0;
        }
        last_pred = argmax;
    }

    for (int i = 0; i < 10; ++i) {
        ress[i] = out[i];
    }
}
